// Valid indicates whether the value is a known member of the WebhookStatus enum.
func (e WebhookStatus) Valid() bool {
	switch e {
	case WebhookStatusACTIVE:
		return true
	case WebhookStatusDISABLED:
		return true
	case WebhookStatusPAUSED:
		return true
	default:
		return false
	}
}

